import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:image_picker/image_picker.dart';
import 'package:permission_handler/permission_handler.dart';
import 'package:speech_to_text/speech_to_text.dart';
import 'core/providers/gemini_client.dart';

void main()=>runApp(const AiOsApp());
const secureStorage=FlutterSecureStorage();
const native=MethodChannel('ai_os/native');

class AiOsApp extends StatelessWidget{const AiOsApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'AI OS',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:const MainShell());}
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}
class _MainShellState extends State<MainShell>{int index=0;@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:IndexedStack(index:index,children:const[ChatPage(),AiRoomPage(),HistoryPage(),SettingsPage()])),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'채팅'),NavigationDestination(icon:Icon(Icons.hub_outlined),label:'AI 대화방'),NavigationDestination(icon:Icon(Icons.history),label:'기록'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'설정')]));}

class ChatPage extends StatefulWidget{const ChatPage({super.key});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final input=TextEditingController();final gemini=const GeminiClient();final stt=SpeechToText();final msgs=<Map<String,String>>[];String? attachmentName,attachmentUri,attachmentText;bool busy=false,listening=false;
Future<void> pickDocument()async{try{final r=await native.invokeMapMethod<String,dynamic>('openDocument');if(r!=null&&mounted){setState((){attachmentName=(r['name']??'문서').toString();attachmentUri=r['uri']?.toString();attachmentText=r['text']?.toString();});}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('문서를 열 수 없습니다: $e')));}}
Future<void> add()async{await showModalBottomSheet<void>(context:context,builder:(x)=>SafeArea(child:Wrap(children:[ListTile(leading:const Icon(Icons.camera_alt_outlined),title:const Text('카메라 촬영'),onTap:()async{Navigator.pop(x);if(await Permission.camera.request().isGranted){final f=await ImagePicker().pickImage(source:ImageSource.camera);if(f!=null&&mounted)setState(()=>attachmentName=f.name);}}),ListTile(leading:const Icon(Icons.photo_library_outlined),title:const Text('사진 선택'),onTap:()async{Navigator.pop(x);final f=await ImagePicker().pickImage(source:ImageSource.gallery);if(f!=null&&mounted)setState(()=>attachmentName=f.name);}),ListTile(leading:const Icon(Icons.description_outlined),title:const Text('문서 선택'),subtitle:const Text('Android 파일 선택기 열기'),onTap:(){Navigator.pop(x);pickDocument();})])));}
Future<void> voice()async{if(listening){await stt.stop();if(mounted)setState(()=>listening=false);return;}if(!await Permission.microphone.request().isGranted)return;final ok=await stt.initialize();if(!ok)return;if(mounted)setState(()=>listening=true);await stt.listen(onResult:(r){input.text=r.recognizedWords;input.selection=TextSelection.collapsed(offset:input.text.length);if(r.finalResult&&mounted)setState(()=>listening=false);});}
String localAnalysis(String q){final d=(attachmentText??'').trim();if(d.isNotEmpty){final sample=d.length>1800?d.substring(0,1800):d;return '로컬 문서 읽기 완료 (${d.length}자)\n\n문서 내용 일부:\n$sample\n\n질문: ${q.isEmpty?'이 문서를 검토해줘':q}\n\n고급 생성형 분석은 연결된 AI가 있을 때 추가로 수행됩니다.';}return '입력은 정상적으로 처리되었습니다. 현재 등록된 외부 AI가 없으므로 기기 내 기본 처리 모드입니다. 생성형 AI 답변이 필요하면 설정에서 사용할 Provider의 API Key를 선택적으로 등록하세요.';}
Future<void> send()async{final q=input.text.trim();if(q.isEmpty&&attachmentName==null)return;setState((){msgs.add({'u':q.isEmpty?'${attachmentName??'첨부'} 분석':q,'a':''});input.clear();busy=true;});final key=await secureStorage.read(key:'gemini_api_key')??'';String ans;if(key.isNotEmpty){try{var p=q.isEmpty?'첨부 자료를 분석해줘':q;if((attachmentText??'').isNotEmpty)p+='\n\n문서 내용:\n${attachmentText!}';ans=await gemini.chat(apiKey:key,prompt:p);}catch(_){ans='연결 AI 응답 실패. 로컬 처리로 전환했습니다.\n\n${localAnalysis(q)}';}}else{ans=localAnalysis(q);}if(mounted)setState((){msgs.add({'u':'','a':ans});attachmentName=null;attachmentUri=null;attachmentText=null;busy=false;});}
@override Widget build(BuildContext c)=>Column(children:[const ListTile(title:Text('AI OS',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:Text('최상의 결과를 위한 AI 운영체제')),Expanded(child:msgs.isEmpty?const Center(child:Text('무엇을 도와드릴까요?',style:TextStyle(fontSize:20))):ListView.builder(padding:const EdgeInsets.all(10),itemCount:msgs.length,itemBuilder:(_,i){final m=msgs[i];final user=m['u']!.isNotEmpty;return Align(alignment:user?Alignment.centerRight:Alignment.centerLeft,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Text(user?m['u']!:m['a']!))));})),if(attachmentName!=null)ListTile(dense:true,leading:const Icon(Icons.attach_file),title:Text(attachmentName!),subtitle:Text(attachmentText==null?'첨부됨':'내용 읽기 완료'),trailing:IconButton(icon:const Icon(Icons.close),onPressed:()=>setState((){attachmentName=null;attachmentUri=null;attachmentText=null;}))),if(busy)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.all(8),child:Row(children:[IconButton(onPressed:add,icon:const Icon(Icons.add_circle_outline)),Expanded(child:TextField(controller:input,minLines:1,maxLines:5,decoration:const InputDecoration(hintText:'메시지',border:OutlineInputBorder()))),IconButton(onPressed:voice,icon:Icon(listening?Icons.mic:Icons.mic_none)),IconButton(onPressed:busy?null:send,icon:const Icon(Icons.send))]))]);}

class AiRoomPage extends StatefulWidget{const AiRoomPage({super.key});@override State<AiRoomPage> createState()=>_AiRoomPageState();}
class _AiRoomPageState extends State<AiRoomPage>{final topics=<String>['AI OS 개발'];String topic='AI OS 개발';final input=TextEditingController();final lines=<String>[];void newTopic(){final c=TextEditingController();showDialog<void>(context:context,builder:(d)=>AlertDialog(title:const Text('새 주제'),content:TextField(controller:c,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('취소')),FilledButton(onPressed:(){final t=c.text.trim();if(t.isNotEmpty)setState((){topics.add(t);topic=t;lines.clear();});Navigator.pop(d);},child:const Text('생성'))]));}void send(){final q=input.text.trim();if(q.isEmpty)return;setState((){lines.add('나: $q');lines.add('Planner: $topic 주제로 요청을 정리했습니다.');lines.add('Reviewer: 추가 검토가 필요한 항목을 확인합니다.');lines.add('Judge: 활성 AI Provider 결과가 있으면 비교 후 최종안을 선정합니다.');input.clear();});}@override Widget build(BuildContext c)=>Column(children:[ListTile(title:const Text('AI 대화방',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:DropdownButton<String>(value:topic,isExpanded:true,items:topics.map((t)=>DropdownMenuItem(value:t,child:Text(t))).toList(),onChanged:(v)=>setState(()=>topic=v!)),trailing:IconButton(icon:const Icon(Icons.add),onPressed:newTopic)),Expanded(child:lines.isEmpty?Center(child:Text('주제: $topic\n직접 메시지를 보내 AI 회의에 참여하세요.',textAlign:TextAlign.center)):ListView.builder(itemCount:lines.length,itemBuilder:(_,i)=>ListTile(title:Text(lines[i])))),Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:input,decoration:const InputDecoration(hintText:'AI 회의에 메시지 입력',border:OutlineInputBorder()))),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]);}
class HistoryPage extends StatelessWidget{const HistoryPage({super.key});@override Widget build(BuildContext c)=>const Center(child:Text('대화 및 작업 기록'));}

class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_SettingsPageState();}
class _SettingsPageState extends State<SettingsPage>{bool freeFirst=true,paid=false;final enabled=<String,bool>{'Gemini':true,'Groq':false,'OpenRouter Free':false,'Hugging Face':false,'OpenAI API':false,'Claude API':false};Future<void> keyDialog(String p)async{final k=p=='Gemini'?'gemini_api_key':'${p.toLowerCase().replaceAll(' ','_')}_api_key';final c=TextEditingController(text:await secureStorage.read(key:k)??'');if(!mounted)return;await showDialog<void>(context:context,builder:(d)=>AlertDialog(title:Text('$p API 설정'),content:TextField(controller:c,obscureText:true,decoration:const InputDecoration(labelText:'API Key (선택사항)',border:OutlineInputBorder())),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('취소')),FilledButton(onPressed:()async{await secureStorage.write(key:k,value:c.text.trim());if(d.mounted)Navigator.pop(d);},child:const Text('저장'))]));}
@override Widget build(BuildContext c)=>ListView(children:[const ListTile(title:Text('설정',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:Text('AI 선택 · API · 권한 · 음성 · 저장공간')),SwitchListTile(value:freeFirst,onChanged:(v)=>setState(()=>freeFirst=v),title:const Text('무료 AI 우선')),SwitchListTile(value:paid,onChanged:(v)=>setState(()=>paid=v),title:const Text('유료 API 사용 허용'),subtitle:const Text('기본 OFF')),const Divider(),...enabled.entries.map((e)=>Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:4),child:Column(children:[SwitchListTile(value:e.value,onChanged:(v)=>setState(()=>enabled[e.key]=v),title:Text(e.key)),TextButton.icon(onPressed:()=>keyDialog(e.key),icon:const Icon(Icons.key),label:const Text('API 설정'))]))),const Divider(),ListTile(leading:const Icon(Icons.mic),title:const Text('마이크 권한'),trailing:TextButton(onPressed:()=>Permission.microphone.request(),child:const Text('요청'))),ListTile(leading:const Icon(Icons.camera_alt),title:const Text('카메라 권한'),trailing:TextButton(onPressed:()=>Permission.camera.request(),child:const Text('요청'))),const ListTile(leading:Icon(Icons.storage),title:Text('저장공간'),subtitle:Text('문서는 Android 시스템 선택기를 사용하며 전체 저장소 권한을 요구하지 않습니다.')),const Divider(),const ListTile(title:Text('AI OS'),subtitle:Text('Version 0.4.0\nCreator: Daehyun Kang'))]);}}
